-- Database: ccbul_db
-- Table: product_margin

DROP TABLE IF EXISTS `product_margin`;
CREATE TABLE `product_margin` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int DEFAULT NULL,
  `site_id` int NOT NULL,
  `marketplace_id` int NOT NULL,
  `product_id` int NOT NULL,
  `variant_id` int NOT NULL DEFAULT '0',
  `item_type` varchar(100) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `user_type` varchar(100) CHARACTER SET latin1 COLLATE latin1_danish_ci NOT NULL,
  `margin_type` varchar(100) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `show_to_user` int DEFAULT NULL,
  `margin` varchar(11) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `MRP` varchar(11) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `mark_up` varchar(255) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `commission_type` varchar(50) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `earning_type` varchar(50) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `earning_scale` varchar(50) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `comm_type` varchar(50) CHARACTER SET latin1 COLLATE latin1_danish_ci DEFAULT NULL,
  `min_order` int NOT NULL,
  `max_order` int NOT NULL,
  `commission_rate` int NOT NULL DEFAULT '0',
  `earning_rate` int NOT NULL DEFAULT '0',
  `vendor_fresh_margin` int DEFAULT '0',
  `commission_split` int DEFAULT '0' COMMENT '0 = Not allowed / \r\n Manually,\r\n 1 = allowed / Automatic',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=latin1 COLLATE=latin1_danish_ci;

